from itertools import product
from functools import lru_cache
@lru_cache(None)
def reference(word):
    if len(word)==1: return {(word[0],1)}
    outcomes=set()
    for split in range(1,len(word)):
        for a,ra in reference(word[:split]):
            for b,rb in reference(word[split:]):
                outcomes.add(((-a-b)%3,ra+1 if ra==rb else max(ra,rb)))
    return outcomes
triples = list(product(range(3),repeat=3))
triple_queries = ['goal'+str(v)+' '+' '.join(map(str,w)) for w in triples for v in sorted({x for x,r in reference(w)})]
triple_grammar = grammar_unbounded().replace(':start ::= query', ':start ::= queries\nqueries ::= query+')
r2 = await aristotle('Constructing triple calibration grammar',operation='create',grammar=triple_grammar)
triple_state=r2['details']['xdev']['inner']['state_id']
await aristotle('Adding all triple result cases',operation='add',state_id=triple_state,fragment='\n'.join(triple_queries))
await aristotle('Parsing all triple result cases',operation='parse',state_id=triple_state)
display({'ordered_triples':len(triples),'attainable_word_value_pairs':len(triple_queries),'register_restriction_misses':sum(any(r>2 for v,r in reference(w)) for w in triples)})

