async def aristotle(purpose, **args):
    started = time.time()
    result = await tool.write(i=purpose, path='xd://reason', content=json.dumps(args))
    experiment_log.append({'call': len(experiment_log)+1, 'purpose': purpose, 'args': args, 'result': result, 'elapsed_seconds': time.time()-started})
    write('experiment8-aristotle.jsonl', ''.join(json.dumps(row, ensure_ascii=False)+'\n' for row in experiment_log))
    inner=result.get('details',{}).get('xdev',{}).get('inner',{})
    display({'call':len(experiment_log), 'purpose':purpose, 'text':result.get('text','')[:1600], 'metrics':{k:v for k,v in inner.items() if k not in ('values','progress')}})
    return result

def grammar_bounded(k):
    lines=[":default ::= action => ::array", ":start ::= query", "query ::= " + ' | '.join(f"'goal{v}' B{v}" for v in range(3))]
    for v in range(3):
        lines.append(f'B{v} ::= '+' | '.join(f'R{r}V{v}' for r in range(1,k+1)))
    for r in range(1,k+1):
        for v in range(3):
            rhs=[f"'{v}'"] if r==1 else []
            for a,b in product(range(3),repeat=2):
                if operation_table[a][b]!=v: continue
                for ra,rb in product(range(1,k+1),repeat=2):
                    if (ra+1 if ra==rb else max(ra,rb))==r:
                        rhs.append(f'R{ra}V{a} R{rb}V{b}')
            lines.append(f'R{r}V{v} ::= '+' | '.join(rhs))
    return '\n'.join(lines+[':discard ~ whitespace',r'whitespace ~ [\s]+'])
r5=await aristotle('Forking register restriction hypothesis',operation='fork',state_id='r1')
bounded_state=r5['details']['xdev']['inner']['state_id']
display({'bounded_state':bounded_state})

