scan=[]
for n in range(1,10):
    histogram={}
    example=None
    for w in product(range(3),repeat=n):
        outcomes=reference(w)
        minima={v:min(r for vv,r in outcomes if vv==v) for v in {vv for vv,r in outcomes}}
        worst=max(minima.values())
        histogram[worst]=histogram.get(worst,0)+1
        if worst>=4 and example is None: example=''.join(map(str,w))
    scan.append({'length':n,'words':3**n,'worst_minimum_register_histogram':histogram,'first_needing_four':example})
write('experiment8-exhaustive.json',json.dumps(scan,indent=2))
display(scan)
