@lru_cache(None)
def count_reference(word):
    if len(word)==1:return {(word[0],1):1}
    counts={}
    for split in range(1,len(word)):
        for (a,ra),na in count_reference(word[:split]).items():
            for (b,rb),nb in count_reference(word[split:]).items():
                key=((-a-b)%3,ra+1 if ra==rb else max(ra,rb))
                counts[key]=counts.get(key,0)+na*nb
    return counts
