91:# Recursively render a parse value into an S-expression string so distinct
92:# parse trees (ambiguities) are visibly different, not just counted.
93:sub _render {
94:    my ($node) = @_;
95:    if (ref($node) eq 'ARRAY') {
96:        return '(' . join(' ', map { _render($_) } @$node) . ')';
97:    } elsif (ref($node) eq 'SCALAR') {
98:        return _render($$node);
99:    } elsif (ref($node) eq 'REF') {
100:        return _render($$node);
101:    } elsif (defined $node) {
102:        return "$node";
103:    } else {
104:        return '';
105:    }
106:}
