108:# Enumerate parse values for $input under $grammar WITHOUT semantic actions,
109:# rendering up to 5 as S-expressions and counting all. This is the ambiguity
110:# oracle: no actions are ever involved, so it is safe to call on any input.
111:sub enumerate_values {
112:    my ($grammar, $input) = @_;
113:
114:    my $recce = Marpa::R2::Scanless::R->new({ grammar => $grammar, semantics_package => 'ReasonTrace' });
115:    my ($status, $error, $value_count, $progress);
116:    my @values = ();
117:    $value_count = 0;
118:
