37:
38:  constructor(perl: string, script: string) {
39:    this.proc = spawn(perl, [script], {
40:      stdio: ["pipe", "pipe", "pipe"],
41:      env: { ...process.env, LC_ALL: "C", LANG: "C" },
42:    });
43:    this.proc.stdout.on("data", (d: Buffer) => this.onData(d));
44:  }
