46:  private onData(d: Buffer) {
47:    this.buffer += d.toString("utf8");
48:    let i: number;
49:    while ((i = this.buffer.indexOf("\n")) >= 0) {
50:      const line = this.buffer.slice(0, i).trim();
51:      this.buffer = this.buffer.slice(i + 1);
52:      if (!line) continue;
53:      let resp: unknown;
54:      try {
55:        resp = JSON.parse(line);
56:      } catch {
57:        continue;
58:      }
59:      this.queue.push(resp);
60:      const w = this.waiters.shift();
61:      if (w) w();
62:    }
63:  }
64:
65:  nextResponse(): Promise<any> {
66:    if (this.queue.length) return Promise.resolve(this.queue.shift());
67:    return new Promise((resolve) => {
68:      this.waiters.push(() => resolve(this.queue.shift()));
69:    });
70:  }
71:
72:  sendRaw(line: string) {
73:    this.proc.stdin.write(line + "\n");
