    $Reason::runtime = { vars => {}, output => [], emitted => [] };
    my $recce = Marpa::R2::Scanless::R->new({ grammar => $grammar, semantics_package => 'Reason' });
    my $ok = eval {
        $recce->read(\$input);
        for (my $i = 1; $i < $index; $i++) { $recce->value(); }
        $Reason::runtime = { vars => {}, output => [], emitted => [] };
        $recce->value();
